const body = $json;

const required = ['credential_id', 'recipients', 'subject', 'body_html'];
const missing = required.filter(f => !body[f]);
if (missing.length > 0) {
  throw new Error('Missing required fields: ' + missing.join(', '));
}
if (!Array.isArray(body.recipients) || body.recipients.length === 0) {
  throw new Error('recipients must be a non-empty array');
}
for (const r of body.recipients) {
  if (!r.email) throw new Error('Each recipient must have an email field');
}

return [{
  json: {
    credential_id: body.credential_id,
    recipients: body.recipients,
    subject: body.subject,
    body_html: body.body_html,
    body_text: body.body_text || '',
    from_name: body.from_name || '',
    reply_to: body.reply_to || '',
    cc: Array.isArray(body.cc) ? body.cc : [],
    bcc: Array.isArray(body.bcc) ? body.bcc : []
  }
}];

const items = $input.all();
if (items.length === 0 || !items[0].json._id) {
  return [{ json: { _found: false } }];
}
return [{ json: { ...items[0].json, _found: true } }];

const cred = $json;

if (!cred.oauth || !cred.oauth.token_expiry) {
  throw new Error('Invalid credential document: missing oauth.token_expiry for credential_id: ' + cred.credential_id);
}

const now = Date.now();
const expiry = new Date(cred.oauth.token_expiry).getTime();

if (now < expiry - 60000) {
  return [{ json: { ...cred, token_refreshed: false } }];
}

const isGmail = cred.provider === 'gmail';
const tokenUrl = isGmail
  ? 'https://oauth2.googleapis.com/token'
  : `https://login.microsoftonline.com/${cred.oauth.tenant_id || 'common'}/oauth2/v2.0/token`;

const reqBody = new URLSearchParams({
  client_id: cred.oauth.client_id,
  client_secret: cred.oauth.client_secret,
  refresh_token: cred.oauth.refresh_token,
  grant_type: 'refresh_token'
}).toString();

const res = await $helpers.httpRequest({
  method: 'POST',
  url: tokenUrl,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: reqBody
});

if (!res.access_token) {
  throw new Error('Token refresh failed: ' + JSON.stringify(res));
}

const newExpiry = new Date(now + res.expires_in * 1000).toISOString();

return [{
  json: {
    ...cred,
    oauth: {
      ...cred.oauth,
      access_token: res.access_token,
      token_expiry: newExpiry
    },
    token_refreshed: true
  }
}];

const creds = $('Code: Get Valid Token').first().json;
const req = $('Code: Validate Input').first().json;

return req.recipients.map(recipient => ({
  json: {
    recipient,
    credential_id: creds.credential_id,
    client_name: creds.client_name || '',
    provider: creds.provider,
    access_token: creds.oauth.access_token,
    from_email: creds.email_address,
    from_name: req.from_name || creds.display_name || '',
    reply_to: req.reply_to || '',
    cc: req.cc || [],
    bcc: req.bcc || [],
    subject: req.subject,
    body_html: req.body_html,
    body_text: req.body_text || ''
  }
}));

const item = $json;
const recipientName = item.recipient.name || '';
const recipientEmail = item.recipient.email;

const subject = item.subject.replace(/\{\{name\}\}/gi, recipientName);
const bodyHtml = item.body_html.replace(/\{\{name\}\}/gi, recipientName);
const bodyText = (item.body_text || bodyHtml.replace(/<[^>]+>/g, '')).replace(/\{\{name\}\}/gi, recipientName);
const fromDisplay = item.from_name ? `${item.from_name} <${item.from_email}>` : item.from_email;
const toDisplay = recipientName ? `${recipientName} <${recipientEmail}>` : recipientEmail;

if (item.provider === 'gmail') {
  const boundary = `boundary_${Date.now()}`;
  const headerLines = [
    `From: ${fromDisplay}`,
    `To: ${toDisplay}`,
    item.cc && item.cc.length ? `Cc: ${item.cc.join(', ')}` : null,
    item.bcc && item.bcc.length ? `Bcc: ${item.bcc.join(', ')}` : null,
    item.reply_to ? `Reply-To: ${item.reply_to}` : null,
    `Subject: =?UTF-8?B?${Buffer.from(subject).toString('base64')}?=`,
    `MIME-Version: 1.0`,
    `Content-Type: multipart/alternative; boundary="${boundary}"`
  ].filter(Boolean).join('\r\n');

  const msgBody = [
    `--${boundary}`,
    `Content-Type: text/plain; charset=UTF-8`,
    ``,
    bodyText,
    `--${boundary}`,
    `Content-Type: text/html; charset=UTF-8`,
    ``,
    bodyHtml,
    `--${boundary}--`
  ].join('\r\n');

  const raw = Buffer.from(`${headerLines}\r\n\r\n${msgBody}`)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');

  return [{ json: { ...item, _subject: subject, payload: { raw } } }];
}

// Outlook / Microsoft Graph
const graphPayload = {
  message: {
    subject,
    body: { contentType: 'HTML', content: bodyHtml },
    toRecipients: [{ emailAddress: { address: recipientEmail, name: recipientName } }],
    ccRecipients: (item.cc || []).map(a => ({ emailAddress: { address: a } })),
    bccRecipients: (item.bcc || []).map(a => ({ emailAddress: { address: a } })),
    replyTo: item.reply_to ? [{ emailAddress: { address: item.reply_to } }] : [],
    from: { emailAddress: { address: item.from_email, name: item.from_name || '' } }
  },
  saveToSentItems: true
};

return [{ json: { ...item, _subject: subject, payload: graphPayload } }];

const context = $('Code: Build Email Payload').item.json;
const response = $json;

let messageId = null;
// Gmail: response has { id, threadId }; Outlook: 202 empty body
if (context.provider === 'gmail' && response.id) {
  messageId = response.id;
} else if (context.provider === 'outlook' && (response.statusCode === 202 || response.status === 202)) {
  messageId = null; // Outlook 202 means accepted, no message id returned
}

return [{
  json: {
    recipient_email: context.recipient.email,
    recipient_name: context.recipient.name || '',
    provider: context.provider,
    credential_id: context.credential_id,
    status: 'sent',
    message_id: messageId,
    subject: context._subject,
    sent_at: new Date().toISOString()
  }
}];

const allResults = $('Code: Normalize Send Result').all().map(i => i.json);
const creds = $('Code: Get Valid Token').first().json;

const summary = {
  total: allResults.length,
  sent: allResults.filter(r => r.status === 'sent').length,
  failed: allResults.filter(r => r.status === 'failed').length
};

return [{
  json: {
    credential_id: creds.credential_id,
    client_name: creds.client_name || '',
    provider: creds.provider,
    sent_at: new Date().toISOString(),
    summary,
    results: allResults
  }
}];
